$ErrorActionPreference='Stop'
$root='D:/VScode/项目/提示词工具/.dsh-workspace/.verification/dsh-web-template-probe-20261102';$profile=Join-Path $root 'profiles/forward-step-web-probe';$cli='D:/deepseek/resources/runtime/cli/bin/dsh.cmd';$env:DSH_HOME=$root;$stdout=Join-Path $root 'web-probe.stdout.log';$stderr=Join-Path $root 'web-probe.stderr.log';$proc=Start-Process -FilePath 'pwsh.exe' -ArgumentList @('-NoProfile','-Command',"`$env:DSH_HOME='$root'; & '$cli' --profile forward-step-web-probe --no-open --host 127.0.0.1 --port 0") -RedirectStandardOutput $stdout -RedirectStandardError $stderr -WindowStyle Hidden -PassThru
